An implementation might look similar to this:

```ts
export function readable<T>(initialValue: T, updater?: Updater<T>) {
  const value = ref(initialValue);
  updater?.((newValue: T) => {
    value.current = newValue;
  });
  return {
    get current() {
      return value.current;
    },
  };
}
```

